in?'positive':'negative' ?>"><?= $in?'+':'-' ?><?= number_format((float)$m['montant'],$m['devise']==='USD'?2:0,',',' ') ?> <?= $m['devise'] ?></td></tr><?php endforeach;?></tbody></table></div></section></div></div><footer class="dashboard-footer">© <?= date('Y') ?> MWIRA Trans <span>Situation financière</span></footer></main></div>
