<script>
const cashData={USD:{in:<?= json_encode($usdIn) ?>,out:<?= json_encode($usdOut) ?>},CDF:{in:<?= json_encode($cdfIn) ?>,out:<?= json_encode($cdfOut) ?>}},cashLabels=<?= json_encode($labels) ?>;let cashChart;function renderCashChart(){const currency=document.getElementById('chart-currency').value;if(cashChart)cashChart.destroy();cashChart=new Chart(document.getElementById('cash-chart'),{type:'bar',data:{labels:cashLabels,datasets:[{label:'Entrées',data:cashData[currency].in,backgroundColor:'#16a34a',borderRadius:5},{label:'Sorties',data:cashData[currency].out,backgroundColor:'#f87171',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',align:'end',labels:{usePointStyle:true,boxWidth:8}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'#e5eee8'},ticks:{callback:v=>v+' '+currency}}}}})}renderCashChart();function switchCashView(v){document.querySelectorAll('.cash-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.getElementById('cash-situation').classList.toggle('hidden',v!=='situation');document.getElementById('cash-mouvements').classList.toggle('hidden',v!=='mouvements')}function filterCash(){const q=document.getElementById('cash-search').value.toLowerCase().trim(),t=document.getElementById('cash-type').value,c=document.getElementById('cash-currency').value;let n=0;document.querySelectorAll('#cash-body tr[data-search]').forEach(r=>{const show=(!q||r.dataset.search.includes(q))&&(!t||r.dataset.type===t)&&(!c||r.dataset.currency===c);r.style.display=show?'':'none';if(show)n++});document.getElementById('cash-count').textContent=n+' mouvement(s)'}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}
function openCashClosing(){document.getElementById('closing-modal').classList.add('show')}function closeCashModal(){document.getElementById('closing-modal').classList.remove('show')}function selectClosingCard(input){document.querySelectorAll('.closing-card').forEach(c=>c.classList.remove('selected'));input.closest('.closing-card').classList.add('selected')}document.addEventListener('DOMContentLoaded',()=>{const heading=document.querySelector('#cash-situation .users-heading');if(heading){const old=heading.querySelector('.cash-updated');const actions=document.createElement('div');actions.className='cash-heading-actions';if(old)actions.appendChild(old);const button=document.createElement('button');button.type='button';button.className='close-vehicle-button';button.innerHTML='<i class="bi bi-lock"></i> Clôturer un véhicule';button.disabled=<?= $vehiculesACloturer?'false':'true' ?>;button.onclick=openCashClosing;actions.appendChild(button);heading.appendChild(actions)}});setTimeout(()=>document.querySelector('.users-toast')?.remove(),4000);
</script></body></html>
